local function overloaded(ctx,e)for _,k in ipairs(ctx:card_definition(ctx:entity(e).card_id).keywords)do if k=="overload"then return true end end return false end
return {api_version=1,id="EX1_258",name="Unbound Elemental",text="After you play a card with <b>Overload</b>, gain +1/+1.",set="EXPERT1",type="minion",class="shaman",rarity="common",cost=3,attack=3,health=4,tags={"elemental"},triggers={{event="card_played",timing="after",active_zones={"board"},condition=function(ctx,self,e)return e.player==ctx:controller(self)and overloaded(ctx,e.entity)end,effect=function(ctx,self)ctx:buff(self,1,1)end}}}
